// gen:types adds the Paisa import to binding files that use it (plan 02 decision).

import { describe, expect, it } from 'vitest';
import { PAISA_IMPORT, addPaisaImport } from '../../../scripts/bindings-paisa.mjs';

const HEADER =
  '// This file was generated by [ts-rs](https://github.com/Aleph-Alpha/ts-rs). Do not edit this file manually.';

describe('addPaisaImport', () => {
  it('adds the import after the ts-rs header when a field is Paisa', () => {
    const source = `${HEADER}\n\nexport type Bill = { total: Paisa, note: string, };\n`;
    expect(addPaisaImport(source)).toBe(
      `${HEADER}\n${PAISA_IMPORT}\n\nexport type Bill = { total: Paisa, note: string, };\n`,
    );
  });

  it('adds it for Paisa inside generics and unions', () => {
    const source = `${HEADER}\nexport type Split = { parts: Array<Paisa>, extra: Paisa | null, };\n`;
    expect(addPaisaImport(source)).toContain(PAISA_IMPORT);
  });

  it('leaves files without Paisa unchanged', () => {
    const source = `${HEADER}\n\nexport type AppInfo = { version: string, identifier: string, };\n`;
    expect(addPaisaImport(source)).toBe(source);
  });

  it('ignores the word in comments and in longer names', () => {
    const source = `${HEADER}\n/**\n * Amount in Paisa.\n */\nexport type Row = { totalPaisa: number, PaisaLike: string, };\n`;
    expect(addPaisaImport(source)).toBe(source);
  });

  it('does not add a second import, so running gen:types twice gives the same file', () => {
    const once = addPaisaImport(`${HEADER}\nexport type Bill = { total: Paisa, };\n`);
    expect(addPaisaImport(once)).toBe(once);
  });
});
